  }
  if (typeof value.time0 !== 'number' || !Number.isFinite(value.time0)) {
    malformed(tag, 'time0 must be a finite number')
  }
  const data = value.data
  if (!isRecord(data)) malformed(tag, 'data must be an object')
  if (tag === 'tool-call-chunks') {
