 * between two safe-integer timestamps exceeds the exact double range, then
 * `next.time - prev.time` rounds, and `prev.time + (next.time - prev.time)`
 * would not equal `next.time` — a packed row would decode to a different time.
 */
function continues(prev: DeltaEvent, next: DeltaEvent, kind: DeltaKind): boolean {
  if (next.seq !== prev.seq + 1) return false
  if (next.data.turn !== prev.data.turn || next.data.step !== prev.data.step) return false
  if (indexOf(next) !== indexOf(prev)) return false
  // Time-gap exactness guard: the gap must be exactly representable so that
  // `prev.time + gap === next.time` holds after float addition. When both
  // endpoints are safe integers but their difference exceeds 2^53, the
  // subtraction rounds and the reconstruction would drift.
  const gap = next.time - prev.time
  if (prev.time + gap !== next.time) return false
  if (kind !== 'tool-call-delta') return true
  const a = toolCallOf(prev)
  const b = toolCallOf(next)
  // `name` must match in presence AND value — a mixed run is not representable.
  return a.id === b.id && Object.hasOwn(a, 'name') === Object.hasOwn(b, 'name') && a.name === b.name
