  register<
    K extends keyof SessionProjectionMap,
    S extends SessionProjectionStateMap[K],
  >(
    definition: Omit<ProjectionDefinition<K, S>, 'wire' | 'persist'> & {
      wire: NonNullable<ProjectionDefinition<K, S>['wire']>
