     ts-types.ts's renderSupportedSchema; the two sibling renderers keep symmetric shapes. */
  const finish = (type: string): void => {
    frames.pop()
    const parent = frames.at(-1)
    if (parent === undefined) result = type
    else parent.childTypes.push(type)
  }

