    schema: unknown
    className: string
    phase: 'start' | 'children'
    kind?: 'oneOf' | 'array' | 'typeddict'
    node?: Record<string, unknown>
    children: { schema: unknown; className: string }[]
    childIndex: number
    childTypes: string[]
    entries: [string, unknown][]
    allocated?: string
    validated: boolean
