        /* v8 ignore next -- childIndex is bounded by children.length. */
        if (child === undefined) throw new Error('missing python render child')
        frame.childIndex++
        frames.push(newFrame(child.schema, child.className, true))
        continue
      }
      if (frame.kind === 'oneOf') {
        finish(frame.childTypes.join(' | '))
        continue
      }
      /* jscpd:ignore-end */
      if (frame.kind === 'array') {
